 FOR spec IN SELECT value FROM jsonb_array_elements($BANK_JSON$[{"course":52,"course_name":"Thực hành Học sâu","order":2,"topic":"NumPy, Pandas và TensorFlow","questions":[{"text":"NumPy ndarray dùng để làm gì?","options":["Kích thước theo từng trục của mảng","Gom các bản ghi theo khóa để tính toán theo nhóm","Lưu và tính toán trên mảng số nhiều chiều","Đưa các đặc trưng về thang đo phù hợp"],"correct":2},{"text":"Trong NumPy, shape biểu thị thông tin nào?","options":["Đọc dữ liệu CSV vào DataFrame","Bỏ mẫu hoặc điền giá trị dựa trên ngữ cảnh dữ liệu","Gom các bản ghi theo khóa để tính toán theo nhóm","Kích thước theo từng trục của mảng"],"correct":3},{"text":"Pandas DataFrame là gì?","options":["Gom các bản ghi theo khóa để tính toán theo nhóm","Đọc dữ liệu CSV vào DataFrame","Đưa các đặc trưng về thang đo phù hợp","Cấu trúc bảng có hàng và cột gắn nhãn"],"correct":3},{"text":"Hàm read_csv của pandas dùng để làm gì?","options":["Đọc dữ liệu CSV vào DataFrame","Xây dựng và huấn luyện mô hình học máy","Lưu và tính toán trên mảng số nhiều chiều","Mảng số với hình dạng và kiểu dữ liệu xác định"],"correct":0},{"text":"Xử lý missing values cần cân nhắc điều gì?","options":["Cấu trúc bảng có hàng và cột gắn nhãn","Đọc dữ liệu CSV vào DataFrame","Bỏ mẫu hoặc điền giá trị dựa trên ngữ cảnh dữ liệu","Kích thước theo từng trục của mảng"],"correct":2},{"text":"TensorFlow chủ yếu hỗ trợ tác vụ nào?","options":["Xây dựng và huấn luyện mô hình học máy","Đọc dữ liệu CSV vào DataFrame","Rò rỉ thống kê từ tập test vào train","Kích thước theo từng trục của mảng"],"correct":0},{"text":"Tensor biểu diễn điều gì?","options":["Mảng số với hình dạng và kiểu dữ liệu xác định","Bỏ mẫu hoặc điền giá trị dựa trên ngữ cảnh dữ liệu","Đưa các đặc trưng về thang đo phù hợp","Kích thước theo từng trục của mảng"],"correct":0},{"text":"Chuẩn hóa đặc trưng trước khi train nhằm mục đích gì?","options":["Đưa các đặc trưng về thang đo phù hợp","Đọc dữ liệu CSV vào DataFrame","Rò rỉ thống kê từ tập test vào train","Bỏ mẫu hoặc điền giá trị dựa trên ngữ cảnh dữ liệu"],"correct":0},{"text":"Tách train và test trước khi chuẩn hóa giúp tránh gì?","options":["Cấu trúc bảng có hàng và cột gắn nhãn","Rò rỉ thống kê từ tập test vào train","Đưa các đặc trưng về thang đo phù hợp","Gom các bản ghi theo khóa để tính toán theo nhóm"],"correct":1},{"text":"Trong pandas, groupby có tác dụng gì?","options":["Cấu trúc bảng có hàng và cột gắn nhãn","Gom các bản ghi theo khóa để tính toán theo nhóm","Mảng số với hình dạng và kiểu dữ liệu xác định","Rò rỉ thống kê từ tập test vào train"],"correct":1}]},{"course":52,"course_name":"Thực hành Học sâu","order":3,"topic":"ANN","questions":[{"text":"ANN là viết tắt của gì?","options":["Từ 0 đến 1","Tổng có trọng số cộng bias trước hàm kích hoạt","0","Artificial Neural Network"],"correct":3},{"text":"Một neuron nhận đầu vào để tính gì?","options":["Đo chênh lệch giữa dự đoán và mục tiêu","Gradient của loss theo tham số","Theo dõi khả năng tổng quát và chọn cấu hình","Tổng có trọng số cộng bias trước hàm kích hoạt"],"correct":3},{"text":"Hàm ReLU trả giá trị nào khi đầu vào âm?","options":["0","Tổng có trọng số cộng bias trước hàm kích hoạt","Artificial Neural Network","Biến đổi biểu diễn đầu vào qua nhiều mức"],"correct":0},{"text":"Hàm sigmoid đưa số thực vào khoảng nào?","options":["Tổng có trọng số cộng bias trước hàm kích hoạt","Từ 0 đến 1","Số mẫu dùng cho một lần cập nhật","Giảm hàm mất mát theo gradient hoặc phương pháp tối ưu"],"correct":1},{"text":"Tầng hidden trong ANN có nhiệm vụ gì?","options":["Đo chênh lệch giữa dự đoán và mục tiêu","Tổng có trọng số cộng bias trước hàm kích hoạt","Gradient của loss theo tham số","Biến đổi biểu diễn đầu vào qua nhiều mức"],"correct":3},{"text":"Loss function dùng để làm gì?","options":["Theo dõi khả năng tổng quát và chọn cấu hình","Giảm hàm mất mát theo gradient hoặc phương pháp tối ưu","Đo chênh lệch giữa dự đoán và mục tiêu","Từ 0 đến 1"],"correct":2},{"text":"Backpropagation giúp tính gì?","options":["Đo chênh lệch giữa dự đoán và mục tiêu","0","Tổng có trọng số cộng bias trước hàm kích hoạt","Gradient của loss theo tham số"],"correct":3},{"text":"Optimizer cập nhật trọng số nhằm mục tiêu gì?","options":["Từ 0 đến 1","Artificial Neural Network","Giảm hàm mất mát theo gradient hoặc phương pháp tối ưu","0"],"correct":2},{"text":"Batch size nghĩa là gì?","options":["Đo chênh lệch giữa dự đoán và mục tiêu","Số mẫu dùng cho một lần cập nhật","Theo dõi khả năng tổng quát và chọn cấu hình","Artificial Neural Network"],"correct":1},{"text":"Vì sao cần validation set khi train ANN?","options":["Số mẫu dùng cho một lần cập nhật","Theo dõi khả năng tổng quát và chọn cấu hình","Tổng có trọng số cộng bias trước hàm kích hoạt","Đo chênh lệch giữa dự đoán và mục tiêu"],"correct":1}]},{"course":52,"course_name":"Thực hành Học sâu","order":4,"topic":"CNN","questions":[{"text":"CNN thường mạnh trong xử lý dữ liệu nào?","options":["Dùng lại trọng số đã học và tinh chỉnh cho tác vụ mới","Tạo biến thể dữ liệu train để tăng tính tổng quát","Kết quả kích hoạt của bộ lọc trên đầu vào","Ảnh và dữ liệu có cấu trúc lưới"],"correct":3},{"text":"Convolution kernel là gì?","options":["Bộ lọc nhỏ trượt trên đầu vào để trích đặc trưng","Bước dịch chuyển của bộ lọc","Cùng bộ lọc áp dụng ở nhiều vị trí","Giá trị lớn nhất trong vùng 2x2"],"correct":0},{"text":"Stride trong convolution nghĩa là gì?","options":["Bước dịch chuyển của bộ lọc","Ảnh và dữ liệu có cấu trúc lưới","Kiểm soát kích thước biên của feature map","Giảm độ phân giải không gian và tổng hợp đặc trưng"],"correct":0},{"text":"Padding thường có mục đích gì?","options":["Bộ lọc nhỏ trượt trên đầu vào để trích đặc trưng","Kiểm soát kích thước biên của feature map","Ảnh và dữ liệu có cấu trúc lưới","Giảm độ phân giải không gian và tổng hợp đặc trưng"],"correct":1},{"text":"Pooling làm gì?","options":["Giảm độ phân giải không gian và tổng hợp đặc trưng","Giá trị lớn nhất trong vùng 2x2","Ảnh và dữ liệu có cấu trúc lưới","Tạo biến thể dữ liệu train để tăng tính tổng quát"],"correct":0},{"text":"Max pooling 2x2 lấy giá trị gì?","options":["Giá trị lớn nhất trong vùng 2x2","Bộ lọc nhỏ trượt trên đầu vào để trích đặc trưng","Kiểm soát kích thước biên của feature map","Tạo biến thể dữ liệu train để tăng tính tổng quát"],"correct":0},{"text":"Feature map là gì?","options":["Kết quả kích hoạt của bộ lọc trên đầu vào","Bước dịch chuyển của bộ lọc","Bộ lọc nhỏ trượt trên đầu vào để trích đặc trưng","Tạo biến thể dữ liệu train để tăng tính tổng quát"],"correct":0},{"text":"Tầng convolution thường chia sẻ tham số theo cách nào?","options":["Giảm độ phân giải không gian và tổng hợp đặc trưng","Ảnh và dữ liệu có cấu trúc lưới","Cùng bộ lọc áp dụng ở nhiều vị trí","Tạo biến thể dữ liệu train để tăng tính tổng quát"],"correct":2},{"text":"Data augmentation giúp ích gì?","options":["Bước dịch chuyển của bộ lọc","Kiểm soát kích thước biên của feature map","Dùng lại trọng số đã học và tinh chỉnh cho tác vụ mới","Tạo biến thể dữ liệu train để tăng tính tổng quát"],"correct":3},{"text":"Khi dùng pretrained CNN để transfer learning thường làm gì?","options":["Ảnh và dữ liệu có cấu trúc lưới","Giảm độ phân giải không gian và tổng hợp đặc trưng","Dùng lại trọng số đã học và tinh chỉnh cho tác vụ mới","Bước dịch chuyển của bộ lọc"],"correct":2}]},{"course":52,"course_name":"Thực hành Học sâu","order":5,"topic":"Autoencoder","questions":[{"text":"Autoencoder có hai phần chính nào?","options":["Khôi phục dữ liệu sạch từ dữ liệu có nhiễu","Tái tạo đầu vào từ biểu diễn tiềm ẩn","Có thể học sao chép đầu vào mà không học đặc trưng hữu ích","Encoder và Decoder"],"correct":3},{"text":"Encoder có chức năng gì?","options":["Nén đầu vào thành biểu diễn tiềm ẩn","Buộc mô hình học biểu diễn cô đọng","Biểu diễn nén do encoder học được","Có thể học sao chép đầu vào mà không học đặc trưng hữu ích"],"correct":0},{"text":"Decoder có chức năng gì?","options":["Tái tạo đầu vào từ biểu diễn tiềm ẩn","Có thể học sao chép đầu vào mà không học đặc trưng hữu ích","Encoder và Decoder","Không cần nhãn phân loại cho mục tiêu tái tạo"],"correct":0},{"text":"Loss thường dùng với autoencoder tái tạo ảnh liên tục là gì?","options":["Encoder và Decoder","Buộc mô hình học biểu diễn cô đọng","Sai số tái tạo giữa ảnh đầu vào và đầu ra","Biểu diễn nén do encoder học được"],"correct":2},{"text":"Latent vector là gì?","options":["Khôi phục dữ liệu sạch từ dữ liệu có nhiễu","Biểu diễn nén do encoder học được","Không cần nhãn phân loại cho mục tiêu tái tạo","Nén đầu vào thành biểu diễn tiềm ẩn"],"correct":1},{"text":"Denoising autoencoder được huấn luyện để làm gì?","options":["Encoder và Decoder","Biểu diễn nén do encoder học được","Không cần nhãn phân loại cho mục tiêu tái tạo","Khôi phục dữ liệu sạch từ dữ liệu có nhiễu"],"correct":3},{"text":"Autoencoder có thể ứng dụng phát hiện bất thường thế nào?","options":["Không cần nhãn phân loại cho mục tiêu tái tạo","Quan sát lỗi tái tạo lớn trên mẫu bất thường","Buộc mô hình học biểu diễn cô đọng","Tái tạo đầu vào từ biểu diễn tiềm ẩn"],"correct":1},{"text":"Bottleneck layer có mục đích gì?","options":["Buộc mô hình học biểu diễn cô đọng","Encoder và Decoder","Khôi phục dữ liệu sạch từ dữ liệu có nhiễu","Nén đầu vào thành biểu diễn tiềm ẩn"],"correct":0},{"text":"Autoencoder cơ bản có cần nhãn phân loại không?","options":["Quan sát lỗi tái tạo lớn trên mẫu bất thường","Không cần nhãn phân loại cho mục tiêu tái tạo","Nén đầu vào thành biểu diễn tiềm ẩn","Có thể học sao chép đầu vào mà không học đặc trưng hữu ích"],"correct":1},{"text":"Nguy cơ khi autoencoder có quá nhiều năng lực biểu diễn là gì?","options":["Có thể học sao chép đầu vào mà không học đặc trưng hữu ích","Buộc mô hình học biểu diễn cô đọng","Sai số tái tạo giữa ảnh đầu vào và đầu ra","Quan sát lỗi tái tạo lớn trên mẫu bất thường"],"correct":0}]},{"course":52,"course_name":"Thực hành Học sâu","order":6,"topic":"RNN","questions":[{"text":"RNN thích hợp với loại dữ liệu nào?","options":["Trục thời gian hoặc độ dài chuỗi","Mang thông tin ngữ cảnh từ bước trước","Lan truyền gradient qua các bước thời gian của chuỗi","Chuỗi có thứ tự thời gian hoặc vị trí"],"correct":3},{"text":"Hidden state trong RNN dùng để làm gì?","options":["Lan truyền gradient qua các bước thời gian của chuỗi","Trục thời gian hoặc độ dài chuỗi","Theo các bước thời gian","Mang thông tin ngữ cảnh từ bước trước"],"correct":3},{"text":"RNN dùng chung tham số theo chiều nào?","options":["Chuỗi có thứ tự thời gian hoặc vị trí","Theo các bước thời gian","Trục thời gian hoặc độ dài chuỗi","Mô hình hóa chuỗi"],"correct":1},{"text":"Backpropagation Through Time là gì?","options":["Theo các bước thời gian","Mang thông tin ngữ cảnh từ bước trước","Đầu ra đúng trước đó làm đầu vào ở bước train","Lan truyền gradient qua các bước thời gian của chuỗi"],"correct":3},{"text":"Vanishing gradient gây khó khăn gì?","options":["Trục thời gian hoặc độ dài chuỗi","Mang thông tin ngữ cảnh từ bước trước","Mô hình hóa chuỗi","Khó học phụ thuộc xa trong chuỗi"],"correct":3},{"text":"Bài toán dự đoán từ tiếp theo thuộc dạng nào?","options":["Mang thông tin ngữ cảnh từ bước trước","Mô hình hóa chuỗi","Khó học phụ thuộc xa trong chuỗi","Trục thời gian hoặc độ dài chuỗi"],"correct":1},{"text":"Dữ liệu đầu vào RNN thường có thêm trục nào?","options":["Đầu ra đúng trước đó làm đầu vào ở bước train","Trục thời gian hoặc độ dài chuỗi","Ghép chúng thành batch có cùng kích thước","Khó học phụ thuộc xa trong chuỗi"],"correct":1},{"text":"Teacher forcing trong mô hình chuỗi dùng thông tin gì?","options":["Mang thông tin ngữ cảnh từ bước trước","Đầu ra đúng trước đó làm đầu vào ở bước train","Chuỗi có thứ tự thời gian hoặc vị trí","Kết hợp ngữ cảnh từ cả hai hướng chuỗi"],"correct":1},{"text":"RNN hai chiều (bidirectional) khác RNN một chiều ở đâu?","options":["Chuỗi có thứ tự thời gian hoặc vị trí","Kết hợp ngữ cảnh từ cả hai hướng chuỗi","Đầu ra đúng trước đó làm đầu vào ở bước train","Mô hình hóa chuỗi"],"correct":1},{"text":"Vì sao cần padding cho các chuỗi có độ dài khác nhau?","options":["Ghép chúng thành batch có cùng kích thước","Đầu ra đúng trước đó làm đầu vào ở bước train","Trục thời gian hoặc độ dài chuỗi","Theo các bước thời gian"],"correct":0}]},{"course":52,"course_name":"Thực hành Học sâu","order":7,"topic":"LSTM","questions":[{"text":"LSTM là biến thể của kiến trúc nào?","options":["Mức độ đưa thông tin từ cell state ra hidden state","Mạng nơron hồi tiếp RNN","Hidden state","Có, gradient vẫn được lan truyền qua thời gian"],"correct":1},{"text":"Cell state trong LSTM dùng để làm gì?","options":["Mức độ giữ hoặc loại thông tin cũ","Mạng nơron hồi tiếp RNN","Mức độ ghi thông tin mới vào cell state","Lưu luồng thông tin dài hạn qua nhiều bước"],"correct":3},{"text":"Forget gate điều khiển việc gì?","options":["Mức độ ghi thông tin mới vào cell state","Mức độ đưa thông tin từ cell state ra hidden state","Dự báo chuỗi thời gian hoặc xử lý ngôn ngữ","Mức độ giữ hoặc loại thông tin cũ"],"correct":3},{"text":"Input gate điều khiển việc gì?","options":["Lưu luồng thông tin dài hạn qua nhiều bước","Mức độ ghi thông tin mới vào cell state","Dự báo chuỗi thời gian hoặc xử lý ngôn ngữ","Mạng nơron hồi tiếp RNN"],"correct":1},{"text":"Output gate điều khiển việc gì?","options":["Lưu luồng thông tin dài hạn qua nhiều bước","Mức độ đưa thông tin từ cell state ra hidden state","Hidden state","Mạng nơron hồi tiếp RNN"],"correct":1},{"text":"LSTM cải thiện điểm yếu nào của RNN thường?","options":["Khó học quan hệ phụ thuộc dài hạn","Mạng nơron hồi tiếp RNN","Lưu luồng thông tin dài hạn qua nhiều bước","Mức độ đưa thông tin từ cell state ra hidden state"],"correct":0},{"text":"LSTM thường được dùng cho bài toán nào?","options":["Dự báo chuỗi thời gian hoặc xử lý ngôn ngữ","Có, gradient vẫn được lan truyền qua thời gian","Mức độ ghi thông tin mới vào cell state","Nhiều cổng và tham số hơn để kiểm soát bộ nhớ"],"correct":0},{"text":"Biểu diễn nào mang thông tin ngắn hạn của LSTM?","options":["Hidden state","Lưu luồng thông tin dài hạn qua nhiều bước","Có, gradient vẫn được lan truyền qua thời gian","Mức độ ghi thông tin mới vào cell state"],"correct":0},{"text":"BPTT vẫn được dùng để huấn luyện LSTM không?","options":["Mức độ giữ hoặc loại thông tin cũ","Có, gradient vẫn được lan truyền qua thời gian","Lưu luồng thông tin dài hạn qua nhiều bước","Mức độ đưa thông tin từ cell state ra hidden state"],"correct":1},{"text":"So với RNN đơn giản, LSTM thường có đặc điểm nào?","options":["Mạng nơron hồi tiếp RNN","Mức độ ghi thông tin mới vào cell state","Mức độ giữ hoặc loại thông tin cũ","Nhiều cổng và tham số hơn để kiểm soát bộ nhớ"],"correct":3}]},{"course":53,"course_name":"Thực hành Trí tuệ nhân tạo","order":2,"topic":"Python nền tảng","questions":[{"text":"List trong Python có đặc điểm nào?","options":["Cú pháp tạo danh sách từ biểu thức và vòng lặp","Khai báo hàm","Có thứ tự và có thể thay đổi","Số phần tử của đối tượng hỗ trợ độ dài"],"correct":2},{"text":"Tuple trong Python khác list ở điểm nào?","options":["Tuple bất biến sau khi tạo","Có thứ tự và có thể thay đổi","Số phần tử của đối tượng hỗ trợ độ dài","Khóa và giá trị"],"correct":0},{"text":"Dictionary lưu dữ liệu theo mô hình nào?","options":["Có thứ tự và có thể thay đổi","Khóa và giá trị","Số phần tử của đối tượng hỗ trợ độ dài","Tuple bất biến sau khi tạo"],"correct":1},{"text":"Từ khóa def dùng để làm gì?","options":["Khai báo hàm","Khóa và giá trị","Có thứ tự và có thể thay đổi","Lặp qua các phần tử của iterable"],"correct":0},{"text":"Vòng lặp for dùng để làm gì?","options":["Có thứ tự và có thể thay đổi","Khóa và giá trị","Lặp qua các phần tử của iterable","pip trong môi trường phù hợp"],"correct":2},{"text":"Biểu thức if dùng để làm gì?","options":["Có thứ tự và có thể thay đổi","Rẽ nhánh theo điều kiện","Khai báo hàm","Tuple bất biến sau khi tạo"],"correct":1},{"text":"Lệnh len trả về thông tin nào?","options":["Có thứ tự và có thể thay đổi","Cú pháp tạo danh sách từ biểu thức và vòng lặp","Tup