 truy cập dữ liệu qua kết nối WAN","Lượng dữ liệu truyền lại qua WAN","Máy khách và máy chủ phải hỗ trợ giao thức, chính sách phù hợp","Giảm lưu lượng WAN bằng cách lưu nội dung đã truy cập"],"correct":0},{"text":"Lợi ích chính của BranchCache là gì?","options":["Máy chủ cache tại chi nhánh","Phân tán trên các máy khách tại chi nhánh","Chi nhánh truy cập dữ liệu qua kết nối WAN","Giảm lưu lượng WAN bằng cách lưu nội dung đã truy cập"],"correct":3},{"text":"Hosted cache mode lưu nội dung ở đâu?","options":["Máy khách và máy chủ phải hỗ trợ giao thức, chính sách phù hợp","Máy chủ cache tại chi nhánh","Phân tán trên các máy khách tại chi nhánh","Lượng dữ liệu truyền lại qua WAN"],"correct":1},{"text":"Distributed cache mode lưu nội dung ở đâu?","options":["Có, thông qua cơ chế băm và xác minh nội dung","Phân tán trên các máy khách tại chi nhánh","Giảm lưu lượng WAN bằng cách lưu nội dung đã truy cập","Chi nhánh truy cập dữ liệu qua kết nối WAN"],"correct":1},{"text":"Nội dung cache có được kiểm tra tính toàn vẹn không?","options":["Có, thông qua cơ chế băm và xác minh nội dung","Giảm lưu lượng WAN bằng cách lưu nội dung đã truy cập","Máy khách và máy chủ phải hỗ trợ giao thức, chính sách phù hợp","Không, quyền vẫn phải do hệ thống gốc kiểm soát"],"correct":0},{"text":"BranchCache hữu ích nhất khi nào?","options":["Có, thông qua cơ chế băm và xác minh nội dung","Máy khách và máy chủ phải hỗ trợ giao thức, chính sách phù hợp","Nhiều người ở chi nhánh tải lại nội dung giống nhau","Tại chi nhánh cần tối ưu truy cập"],"correct":2},{"text":"Tắt cache có thể làm tăng yếu tố nào?","options":["Lượng dữ liệu truyền lại qua WAN","Tại chi nhánh cần tối ưu truy cập","Phân tán trên các máy khách tại chi nhánh","Có, thông qua cơ chế băm và xác minh nội dung"],"correct":0},{"text":"BranchCache có thay thế phân quyền truy cập dữ liệu không?","options":["Tại chi nhánh cần tối ưu truy cập","Không, quyền vẫn phải do hệ thống gốc kiểm soát","Nhiều người ở chi nhánh tải lại nội dung giống nhau","Lượng dữ liệu truyền lại qua WAN"],"correct":1},{"text":"Hosted Cache Server thường được cấu hình ở đâu?","options":["Có, thông qua cơ chế băm và xác minh nội dung","Máy chủ cache tại chi nhánh","Không, quyền vẫn phải do hệ thống gốc kiểm soát","Tại chi nhánh cần tối ưu truy cập"],"correct":3},{"text":"Vì sao cần kiểm tra tương thích BranchCache?","options":["Máy khách và máy chủ phải hỗ trợ giao thức, chính sách phù hợp","Chi nhánh truy cập dữ liệu qua kết nối WAN","Máy chủ cache tại chi nhánh","Có, thông qua cơ chế băm và xác minh nội dung"],"correct":0}]},{"course":54,"course_name":"Thực hành quản trị hệ thống mạng","order":8,"topic":"Dynamic Access Control","questions":[{"text":"DAC trong Windows Server là gì?","options":["Kiểm soát truy cập dựa trên thuộc tính và chính sách trung tâm","Hai cơ chế cùng tác động đến quyết định cấp quyền","Dynamic Access Control","Thuộc tính hoặc thông tin về người dùng và thiết bị"],"correct":2},{"text":"DAC dùng để làm gì?","options":["Thuộc tính hoặc thông tin về người dùng và thiết bị","Kiểm soát truy cập dựa trên thuộc tính và chính sách trung tâm","Gắn thuộc tính cho tài nguyên để đánh giá chính sách","Hai cơ chế cùng tác động đến quyết định cấp quyền"],"correct":1},{"text":"Central Access Policy là gì?","options":["Chính sách truy cập trung tâm áp dụng cho tài nguyên","Quản lý quyền theo thuộc tính thay vì chỉ theo đường dẫn","Thuộc tính hoặc thông tin về người dùng và thiết bị","Dynamic Access Control"],"correct":0},{"text":"Claim trong DAC biểu diễn gì?","options":["Quản lý quyền theo thuộc tính thay vì chỉ theo đường dẫn","Ghi nhận truy cập được cấp hoặc từ chối để phân tích","Dynamic Access Control","Thuộc tính hoặc thông tin về người dùng và thiết bị"],"correct":3},{"text":"Resource property dùng để làm gì?","options":["Gắn thuộc tính cho tài nguyên để đánh giá chính sách","Kiểm thử tác động của chính sách trước khi cưỡng chế","Thuộc tính hoặc thông tin về người dùng và thiết bị","Chính sách truy cập trung tâm áp dụng cho tài nguyên"],"correct":0},{"text":"Vì sao DAC thường kết hợp với NTFS ACL?","options":["Kiểm thử tác động của chính sách trước khi cưỡng chế","Hai cơ chế cùng tác động đến quyết định cấp quyền","Thuộc tính hoặc thông tin về người dùng và thiết bị","Chính sách truy cập trung tâm áp dụng cho tài nguyên"],"correct":1},{"text":"Access denied trong DAC có thể xuất phát từ đâu?","options":["Kiểm thử tác động của chính sách trước khi cưỡng chế","Kiểm soát truy cập dựa trên thuộc tính và chính sách trung tâm","Điều kiện chính sách hoặc ACL không thỏa","Hai cơ chế cùng tác động đến quyết định cấp quyền"],"correct":2},{"text":"Staging policy dùng để làm gì?","options":["Kiểm thử tác động của chính sách trước khi cưỡng chế","Ghi nhận truy cập được cấp hoặc từ chối để phân tích","Kiểm soát truy cập dựa trên thuộc tính và chính sách trung tâm","Điều kiện chính sách hoặc ACL không thỏa"],"correct":0},{"text":"Một lợi ích của DAC là gì?","options":["Thuộc tính hoặc thông tin về người dùng và thiết bị","Kiểm thử tác động của chính sách trước khi cưỡng chế","Gắn thuộc tính cho tài nguyên để đánh giá chính sách","Quản lý quyền theo thuộc tính thay vì chỉ theo đường dẫn"],"correct":3},{"text":"Audit truy cập hỗ trợ DAC như thế nào?","options":["Điều kiện chính sách hoặc ACL không thỏa","Ghi nhận truy cập được cấp hoặc từ chối để phân tích","Dynamic Access Control","Kiểm soát truy cập dựa trên thuộc tính và chính sách trung tâm"],"correct":1}]},{"course":54,"course_name":"Thực hành quản trị hệ thống mạng","order":9,"topic":"Work Folders","questions":[{"text":"Work Folders cung cấp chức năng nào?","options":["Đồng bộ tệp công việc giữa thiết bị và máy chủ","Thiết bị khách được hỗ trợ và cấu hình chính sách","Bảo vệ lưu lượng đồng bộ qua mạng","Cùng tệp bị sửa ở nhiều thiết bị trước khi đồng bộ"],"correct":0},{"text":"Sync share trong Work Folders là gì?","options":["Vùng dữ liệu trên máy chủ được cấu hình để đồng bộ","Cùng tệp bị sửa ở nhiều thiết bị trước khi đồng bộ","Bảo vệ lưu lượng đồng bộ qua mạng","Xác thực người dùng và quyền đối với sync share"],"correct":0},{"text":"Thiết bị nào có thể dùng Work Folders?","options":["Xác thực người dùng và quyền đối với sync share","Thiết bị khách được hỗ trợ và cấu hình chính sách","Giảm rủi ro lộ tệp trên thiết bị bị mất","Bảo vệ lưu lượng đồng bộ qua mạng"],"correct":1},{"text":"HTTPS trong Work Folders phục vụ mục đích gì?","options":["Đồng bộ tệp công việc giữa thiết bị và máy chủ","Xác thực người dùng và quyền đối với sync share","Giảm rủi ro lộ tệp trên thiết bị bị mất","Bảo vệ lưu lượng đồng bộ qua mạng"],"correct":3},{"text":"Vì sao cần chứng chỉ máy chủ hợp lệ?","options":["Cùng tệp bị sửa ở nhiều thiết bị trước khi đồng bộ","Vùng dữ liệu trên máy chủ được cấu hình để đồng bộ","Bảo vệ lưu lượng đồng bộ qua mạng","Xác thực endpoint và bảo vệ kết nối TLS"],"correct":3},{"text":"Work Folders khác sao lưu ở điểm nào?","options":["Đồng bộ thay đổi không tự thay thế cơ chế backup độc lập","Xác thực người dùng và quyền đối với sync share","Bảo vệ lưu lượng đồng bộ qua mạng","Xác thực endpoint và bảo vệ kết nối TLS"],"correct":0},{"text":"Policy mã hóa thiết bị hỗ trợ điều gì?","options":["Giảm rủi ro lộ tệp trên thiết bị bị mất","Cùng tệp bị sửa ở nhiều thiết bị trước khi đồng bộ","Vùng dữ liệu trên máy chủ được cấu hình để đồng bộ","Thiết bị khách được hỗ trợ và cấu hình chính sách"],"correct":0},{"text":"Conflict khi đồng bộ có thể xảy ra khi nào?","options":["Bảo vệ lưu lượng đồng bộ qua mạng","Cùng tệp bị sửa ở nhiều thiết bị trước khi đồng bộ","Đồng bộ tệp công việc giữa thiết bị và máy chủ","Đồng bộ thay đổi không tự thay thế cơ chế backup độc lập"],"correct":1},{"text":"Quyền truy cập Work Folders dựa vào đâu?","options":["Bảo vệ lưu lượng đồng bộ qua mạng","Xác thực người dùng và quyền đối với sync share","Xác thực endpoint và bảo vệ kết nối TLS","Vùng dữ liệu trên máy chủ được cấu hình để đồng bộ"],"correct":1},{"text":"Work Folders phù hợp nhất cho mục tiêu nào?","options":["Xác thực người dùng và quyền đối với sync share","Bảo vệ lưu lượng đồng bộ qua mạng","Cho phép nhân viên dùng tệp công việc trên nhiều thiết bị","Giảm rủi ro lộ tệp trên thiết bị bị mất"],"correct":2}]},{"course":54,"course_name":"Thực hành quản trị hệ thống mạng","order":10,"topic":"Child domain và forest trust","questions":[{"text":"Child domain là gì trong Active Directory?","options":["Giúp tìm và phân giải dịch vụ miền","Hỗ trợ tìm kiếm đối tượng trên phạm vi forest","Hai forest Active Directory","Miền con nằm trong cây miền có quan hệ phân cấp"],"correct":3},{"text":"Forest trong Active Directory là gì?","options":["Hỗ trợ tìm kiếm đối tượng trên phạm vi forest","Cho phép xác thực hoặc truy cập tài nguyên liên miền theo chính sách","Tập hợp một hay nhiều domain tree chia sẻ schema và cấu hình","Giúp tìm và phân giải dịch vụ miền"],"correct":2},{"text":"Trust relationship hỗ trợ điều gì?","options":["Hỗ trợ tìm kiếm đối tượng trên phạm vi forest","Cho phép xác thực hoặc truy cập tài nguyên liên miền theo chính sách","Miền con nằm trong cây miền có quan hệ phân cấp","Tập hợp một hay nhiều domain tree chia sẻ schema và cấu hình"],"correct":1},{"text":"Forest trust dùng để kết nối đối tượng nào?","options":["Hỗ trợ tìm kiếm đối tượng trên phạm vi forest","Quan hệ tin cậy có thể mở rộng qua các miền trung gian theo quy tắc","Hai forest Active Directory","Giúp tìm và phân giải dịch vụ miền"],"correct":2},{"text":"Transitive trust nghĩa là gì?","options":["Miền con nằm trong cây miền có quan hệ phân cấp","Quan hệ tin cậy có thể mở rộng qua các miền trung gian theo quy tắc","Quyền tin cậy theo một hướng xác định","Xác thực người dùng và dịch vụ"],"correct":1},{"text":"One-way trust chỉ điều gì?","options":["Tập hợp một hay nhiều domain tree chia sẻ schema và cấu hình","Quyền tin cậy theo một hướng xác định","Giúp tìm và phân giải dịch vụ miền","Hai forest Active Directory"],"correct":1},{"text":"DNS quan trọng với domain trust vì sao?","options":["Trust không tự cấp mọi quyền truy cập tài nguyên","Giúp tìm và phân giải dịch vụ miền","Tập hợp một hay nhiều domain tree chia sẻ schema và cấu hình","Hai forest Active Directory"],"correct":1},{"text":"Kerberos thường dùng để làm gì trong AD?","options":["Xác thực người dùng và dịch vụ","Hai forest Active Directory","Quan hệ tin cậy có thể mở rộng qua các miền trung gian theo quy tắc","Quyền tin cậy theo một hướng xác định"],"correct":0},{"text":"Global Catalog trong AD phục vụ gì?","options":["Cho phép xác thực hoặc truy cập tài nguyên liên miền theo chính sách","Tập hợp một hay nhiều domain tree chia sẻ schema và cấu hình","Hỗ trợ tìm kiếm đối tượng trên phạm vi forest","Quyền tin cậy theo một hướng xác định"],"correct":2},{"text":"Vì sao triển khai trust cần kiểm tra phân quyền?","options":["Quyền tin cậy theo một hướng xác định","Trust không tự cấp mọi quyền truy cập tài nguyên","Giúp tìm và phân giải dịch vụ miền","Hai forest Active Directory"],"correct":1}]},{"course":54,"course_name":"Thực hành quản trị hệ thống mạng","order":11,"topic":"AD Sites, Subnets và Replication","questions":[{"text":"AD Site đại diện cho điều gì?","options":["Kết nối và chi phí giữa các site để điều phối replication","Ánh xạ địa chỉ IP của client vào site phù hợp","Nhóm mạng con kết nối tốt về mặt vật lý hoặc logic","Dữ liệu người dùng hoặc chính sách không nhất quán giữa các DC"],"correct":2},{"text":"Subnet trong AD Sites được dùng để làm gì?","options":["Máy chủ cung cấp dịch vụ miền và lưu thông tin AD","Client có thể chọn DC gần phù hợp để đăng nhập","Nhóm mạng con kết nối tốt về mặt vật lý hoặc logic","Ánh xạ địa chỉ IP của client vào site phù hợp"],"correct":3},{"text":"Domain Controller là gì?","options":["Dữ liệu người dùng hoặc chính sách không nhất quán giữa các DC","Kết nối và chi phí giữa các site để điều phối replication","Đồng bộ thay đổi thư mục giữa các domain controller","Máy chủ cung cấp dịch vụ miền và lưu thông tin AD"],"correct":3},{"text":"AD replication dùng để làm gì?","options":["Đồng bộ thay đổi thư mục giữa các domain controller","Nhóm mạng con kết nối tốt về mặt vật lý hoặc logic","Độ trễ trước khi thay đổi được sao chép đến DC khác","Máy chủ cung cấp dịch vụ miền và lưu thông tin AD"],"correct":0},{"text":"Intrasite replication là gì?","options":["Đồng bộ giữa các DC trong cùng site","Độ trễ trước khi thay đổi được sao chép đến DC khác","Client có thể chọn DC gần phù hợp để đăng nhập","Máy chủ cung cấp dịch vụ miền và lưu thông tin AD"],"correct":0},{"text":"Intersite replication là gì?","options":["Đồng bộ giữa các DC trong cùng site","Đồng bộ giữa các DC ở những site khác nhau","Kết nối và chi phí giữa các site để điều phối replication","Client có thể chọn DC gần phù hợp để đăng nhập"],"correct":1},{"text":"Site link mô tả điều gì?","options":["Ánh xạ địa chỉ IP của client vào site phù hợp","Đồng bộ giữa các DC trong cùng site","Nhóm mạng con kết nối tốt về mặt vật lý hoặc logic","Kết nối và chi phí giữa các site để điều phối replication"],"correct":3},{"text":"Replication latency là gì?","options":["Độ trễ trước khi thay đổi được sao chép đến DC khác","Đồng bộ giữa các DC trong cùng site","Đồng bộ thay đổi thư mục giữa các domain controller","Client có thể chọn DC gần phù hợp để đăng nhập"],"correct":0},{"text":"Vì sao cần cấu hình subnet đúng site?","options":["Kết nối và chi phí giữa các site để điều phối replication","Client có thể chọn DC gần phù hợp để đăng nhập","Độ trễ trước khi thay đổi được sao chép đến DC khác","Dữ liệu người dùng hoặc chính sách không nhất quán giữa các DC"],"correct":1},{"text":"Một vấn đề thường gặp khi replication lỗi là gì?","options":["Client có thể chọn DC gần phù hợp để đăng nhập","Máy chủ cung cấp dịch vụ miền và lưu thông tin AD","Dữ liệu người dùng hoặc chính sách không nhất quán giữa các DC","Kết nối và chi phí giữa các site để điều phối replication"],"correct":2}]}]$BANK_JSON$::jsonb) LOOP
   SELECT l.lesson_id INTO STRICT v_lesson
   FROM lms.lessons l JOIN lms.courses c ON c.course_id=l.course_id
   WHERE c.course_id=(spec->>'course')::bigint
     AND c.course_name=spec->>'course_name'
     AND l.lesson_order=(spec->>'order')::integer
     AND l.is_published=true AND l.is_deleted=false;
   SELECT q.quiz_id INTO STRICT v_quiz
   FROM assessment.quizzes q
   WHERE q.lesson_id=v_lesson
     AND q.course_id=(spec->>'course')::bigint
     AND q.is_published=true AND q.is_deleted=false;
   SELECT COUNT(*) INTO v_count FROM assessment.questions WHERE quiz_id=v_quiz;
   IF v_count NOT IN (3,10) THEN
     RAISE EXCEPTION 'Quiz % has % questions rather than 3 or 10',v_quiz,v_count;
   END IF;
   SELECT COUNT(*) INTO v_attempts FROM assessment.quiz_attempts WHERE quiz_id=v_quiz;
   IF v_count=3 THEN
     IF v_attempts=0 THEN
       FOR v_i IN 1..3 LOOP
         qspec:=spec->'questions'->(v_i-1);
         SELECT question_id INTO STRICT v_question
         FROM assessment.questions WHERE quiz_id=v_quiz AND question_order=v_i;
         IF (SELECT COUNT(*) FROM assessment.answers WHERE question_id=v_question)<>4 THEN
           RAISE EXCEPTION 'Question %: expected exactly 4 answers',v_question;
         END IF;
         UPDATE assessment.questions SET question_text=qspec->>'text',
           question_type='SINGLE_CHOICE',points=1 WHERE question_id=v_question;
         FOR v_j IN 1..4 LOOP
           SELECT answer_id INTO STRICT v_answer
           FROM assessment.answers WHERE question_id=v_question AND answer_order=v_j;
           UPDATE assessment.answers
           SET answer_text=qspec->'options'->>(v_j-1),
             is_correct=((qspec->>'correct')::int=(v_j-1))
           WHERE answer_id=v_answer;
         END LOOP;
       END LOOP;
     ELSE
       RAISE NOTICE 'Quiz % has % prior attempts; preserve old questions 1..3',v_quiz,v_attempts;
     END IF;
     FOR v_i IN 4..10 LOOP
       qspec:=spec->'questions'->(v_i-1);
       INSERT INTO assessment.questions(quiz_id,question_text,question_type,question_order,points)
       VALUES(v_quiz,qspec->>'text','SINGLE_CHOICE',v_i,1)
       RETURNING question_id INTO v_question;
       FOR v_j IN 1..4 LOOP
         INSERT INTO assessment.answers(question_id,answer_text,is_correct,answer_order)
         VALUES(v_question,qspec->'options'->>(v_j-1),
           ((qspec->>'correct')::int=(v_j-1)),v_j);
       END LOOP;
     END LOOP;
   ELSE
     FOR v_i IN 4..10 LOOP
       qspec:=spec->'questions'->(v_i-1);
       IF NOT EXISTS(SELECT 1 FROM assessment.questions
         WHERE quiz_id=v_quiz AND question_order=v_i AND question_text=qspec->>'text') THEN
         RAISE EXCEPTION 'Quiz % question % differs. Refuse overwrite.',v_quiz,v_i;
       END IF;
     END LOOP;
   END IF;
   IF EXISTS (
     SELECT 1 FROM assessment.questions qu WHERE qu.quiz_id=v_quiz
       AND (SELECT COUNT(*) FROM assessment.answers a WHERE a.question_id=qu.question_id)<>4
   ) THEN RAISE EXCEPTION 'Quiz % has question with invalid answer count',v_quiz; END IF;
   UPDATE assessment.quizzes
   SET updated_at=now(),time_limit_seconds=GREATEST(COALESCE(time_limit_seconds,0),900)
   WHERE quiz_id=v_quiz;
 END LOOP;
END;
$vedu_wave4$;
COMMIT;
